SELECT s.id || ' — история есть, а ни одна фича её не называет' AS detail FROM project_stories s WHERE s.project_id = $1 AND NOT EXISTS (SELECT 1 FROM project_feature_stories f WHERE f.project_id = s.project_id AND f.story_id = s.id) UNION ALL SELECT f.feature_id || ' → ' || f.story_id || ' — фича называет историю, а такой нет' FROM project_feature_stories f WHERE f.project_id = $1 AND NOT EXISTS (SELECT 1 FROM project_stories s WHERE s.project_id = f.project_id AND s.id = f.story_id) ORDER BY 1
